using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using System.Runtime.InteropServices;using System.Web.Script.Serialization;using interop.ICApiIronCAD;
namespace RockPro{public static class LatchInProcess{public static int Run(string folder){var j=new JavaScriptSerializer{MaxJsonLength=64000000};var r=new Dictionary<string,object>();try{var q=(Dictionary<string,object>)j.DeserializeObject(File.ReadAllText(Path.Combine(folder,"request.json")));if(System.Diagnostics.Process.GetCurrentProcess().Id!=Convert.ToInt32(q["expected_pid"]))throw new Exception("Host changed");dynamic l=Marshal.GetActiveObject("IronCAD.Application");var app=(IZBaseApp)l.ZIronCADApp;if(!app.ApiVersion.StartsWith("29."))throw new Exception("2027 required");bool already;string output=(string)q["output"];var doc=app.OpenFile2(output,false,true,out already);app.ActiveDoc=doc;var loaded=AppDomain.CurrentDomain.GetAssemblies().Where(a=>a.GetType("RockPro.CAD.MountCountController")!=null).ToArray();r["loaded_controllers"]=loaded.Select(a=>a.FullName).ToArray();r["manual_loads"]=0;r["manual_start_calls"]=0;if(loaded.Length!=1)throw new Exception("Expected exactly one auto-loaded controller");var type=loaded[0].GetType("RockPro.CAD.MountCountController");r["timer_started"]=type.GetField("timer",BindingFlags.Static|BindingFlags.NonPublic).GetValue(null)!=null;if(!(bool)r["timer_started"])throw new Exception("Timer not started");r["passed"]=true;}catch(Exception ex){r["passed"]=false;r["error"]=ex.ToString();}File.WriteAllText(Path.Combine(folder,"result.json"),j.Serialize(r));return (bool)r["passed"]?0:1;}}}